        if (obj != null && !type.isAssignableFrom(obj.getClass())) {
            Log log = (conf == null) ? null : conf.getConfigurationLog();
            String msg = getIncompatiblePluginMessage(obj, type);
            if (log != null && log.isErrorEnabled()) {
            	log.error(msg);
